{
  "case_goal": "Add a new announcement with formatted text (bold, italic, center aligned) in the Announcements module after logging in as admin.",
  "summary": "Open the overview page, log in with 'admin'/'admin', navigate to Announcements, click 'Add entry', fill in headline 'test', select category option 'General test', apply bold, italic, and center formatting via CKEditor toolbar, switch to the editor iframe, type 'test' in the description body, and save the announcement.",
  "steps": [
    {
      "action_type": "navigate",
      "target": "url",
      "value": "http://admidio-old.local:8082/adm_program/overview.php",
      "page_url": "http://admidio-old.local:8082/adm_program/overview.php",
      "expected_result": "Page loads with login form visible (input fields for username, password, organization, and sign-in button)."
    },
    {
      "action_type": "login",
      "target": "login form",
      "value": "username='admin', password='admin'",
      "page_url": "http://admidio-old.local:8082/adm_program/overview.php",
      "expected_result": "Login succeeds; page re-renders with 'My profile' and 'Sign out' links in the navigation bar."
    },
    {
      "action_type": "click",
      "target": "link with id='announcements'",
      "value": null,
      "page_url": "http://admidio-old.local:8082/adm_program/modules/announcements/announcements.php",
      "expected_result": "Announcements page loads with 'Add entry' and 'Edit categories' buttons visible."
    },
    {
      "action_type": "click",
      "target": "link with id='menu_item_announcement_add'",
      "value": null,
      "page_url": "http://admidio-old.local:8082/adm_program/modules/announcements/announcements_new.php?headline=Announcements",
      "expected_result": "Add announcement form appears with fields for headline, category, description (CKEditor), and a Save button."
    },
    {
      "action_type": "type",
      "target": "input with id='ann_headline'",
      "value": "test",
      "page_url": "http://admidio-old.local:8082/adm_program/modules/announcements/announcements_new.php?headline=Announcements",
      "expected_result": "Headline field contains 'test'."
    },
    {
      "action_type": "select_option",
      "target": "select with id='ann_cat_id' option[4]",
      "value": "General test",
      "page_url": "http://admidio-old.local:8082/adm_program/modules/announcements/announcements_new.php?headline=Announcements",
      "expected_result": "Category drop-down shows 'General test' selected."
    },
    {
      "action_type": "click",
      "target": "button with id='cke_15' (Bold)",
      "value": null,
      "page_url": "http://admidio-old.local:8082/adm_program/modules/announcements/announcements_new.php?headline=Announcements",
      "expected_result": "Bold button toggled; CKEditor elements path shows 'strong' tag (indicating bold is active)."
    },
    {
      "action_type": "click",
      "target": "button with id='cke_16' (Italic)",
      "value": null,
      "page_url": "http://admidio-old.local:8082/adm_program/modules/announcements/announcements_new.php?headline=Announcements",
      "expected_result": "Italic button toggled; CKEditor elements path shows 'em' tag (indicating italic is active)."
    },
    {
      "action_type": "click",
      "target": "span[1] inside button with id='cke_22' (Center)",
      "value": null,
      "page_url": "http://admidio-old.local:8082/adm_program/modules/announcements/announcements_new.php?headline=Announcements",
      "expected_result": "Center alignment toggled; elements path remains with 'strong' and 'em'."
    },
    {
      "action_type": "switch_frame",
      "target": "iframe within id='cke_1_contents'",
      "value": null,
      "page_url": "http://admidio-old.local:8082/adm_program/modules/announcements/announcements_new.php?headline=Announcements",
      "expected_result": "Focus moves to the rich text editor body (title changes to 'Rich Text Editor, ann_description')."
    },
    {
      "action_type": "type",
      "target": "body element inside iframe",
      "value": "test",
      "page_url": "http://admidio-old.local:8082/adm_program/modules/announcements/announcements_new.php?headline=Announcements",
      "expected_result": "Editor body contains the typed text 'test'."
    },
    {
      "action_type": "click",
      "target": "button with id='btn_save'",
      "value": null,
      "page_url": "http://admidio-old.local:8082/adm_program/modules/announcements/announcements.php",
      "expected_result": "Page redirects back to announcements list; new announcement 'test' by Paul Schmidt is visible with a category link."
    }
  ]
}
